syntax:
enum class EnumName : underlying_type {
    Option1 = value1,
    Option2 = value2,
    // ...
};

// Overload bitwise operators for enum class
inline EnumName operator|(EnumName lhs, EnumName rhs) {
    return static_cast<EnumName>(
        static_cast<std::underlying_type<EnumName>::type>(lhs) |
        static_cast<std::underlying_type<EnumName>::type>(rhs)
    );
}

// Usage: EnumName combined_flags = EnumName::Option1 | EnumName::Option2;

code_example:
#include <iostream>
#include <fstream>
#include <string>
enum class FileMode : std::ios_base::openmode {
    Read = std::ios_base::in,
    Write = std::ios_base::out,
    Append = std::ios_base::app
};

inline FileMode operator|(FileMode lhs, FileMode rhs) {
    return static_cast<FileMode>(
        static_cast<std::underlying_type<FileMode>::type>(lhs) |
        static_cast<std::underlying_type<FileMode>::type>(rhs)
    );
}

int main() {
    FileMode mode = FileMode::Read | FileMode::Write;
    std::fstream file;
    file.open("example.txt", static_cast<std::ios_base::openmode>(mode));
    if (file.is_open()) {
        file << "Hello, C++!";
        file.close();
    }
    return 0;
}
